    [4439]={name="Bruiser Club",quality=2,ilvl=22,reqLevel=17,sourceType="rare_npc",instructions="Drops from Rot Hide Bruiser.",zone="Alterac Mountains",npc="Rot Hide Bruiser"},
    [4443]={name="Grim Pauldrons",quality=2,ilvl=36,reqLevel=27,sourceType="quest_reward",instructions="Reward from the quest 'To Steal From Thieves'. Pick it over the other reward choices. Starts with Genavie Callow in Undercity. Objective: Bring Kenata, Fardel, and Marcel Dabyrie's Heads to Genavie Callow in Undercity.",zone="Undercity",questName="To Steal From Thieves",lore="The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed! My family is gone, taken by the plague."},
    [4444]={name="Black Husk Shield",quality=2,ilvl=26,reqLevel=21,sourceType="rare_npc",instructions="Drops from Leech Widow.",zone="Wetlands",npc="Leech Widow"},
