    [6392]={name="Belt of Arugal",quality=3,ilvl=28,reqLevel=23,sourceType="boss_drop",instructions="Drops from Archmage Arugal.",zone="Shadowfang Keep",npc="Archmage Arugal",lore="Arugal's own belt. He summoned the worgen to save Silverpine, then lost his mind in Shadowfang Keep surrounded by what he had called."},
