    [9389]={name="Revelosh's Spaulders",quality=3,ilvl=42,reqLevel=37,sourceType="boss_drop",instructions="Drops from Revelosh.",zone="Uldaman",npc="Revelosh",lore="Revelosh was a Shadowforge explorer who went into Uldaman looking for the origin of the dwarves, and became part of the ruin instead."},
