    [19392]={name="Girdle of the Fallen Crusader",quality=4,ilvl=77,reqLevel=60,sourceType="boss_drop",instructions="Drops from Chromaggus.",zone="Blackwing Lair",npc="Chromaggus",lore="Nefarian's best result: a two-headed chromatic horror carrying the breath of every dragonflight at once."},
    [19395]={name="Rejuvenating Gem",quality=4,ilvl=75,reqLevel=60,sourceType="boss_drop",instructions="Drops from Ebonroc.",zone="Blackwing Lair",npc="Ebonroc",lore="One of three drakes guarding Nefarian's inner lair, and the one that heals itself off the wounds it deals."},
